mapper.select:
select
t1.*,
t2.score_template_hd_name score_template_hd_id_n
from
hls_score_calculation t1,
fnd_score_template_hd t2
where
t1.score_template_hd_id = t2.score_template_hd_id

    and t1.company_id = #{companyId}


    and t1.object_id = #{objectId}


    and t1.fiscal_year = #{fiscalYear}


    and t1.fiscal_month = #{fiscalMonth}


    AND t1.score_template_hd_id = #{scoreTemplateHdId}


    and t1.SCORE_ID = #{scoreId}
